cd /REPO-spec && cat > App/InterviewStarterApp.swift <<'EOF'
import APIClient
import APIClientLive
import AppCore
import AppUI
import ComposableArchitecture
import Foundation
import LogClientLive
import SwiftUI

/// Composition root: the only place that links the `*Live` client modules, whose `DependencyKey`
/// conformances supply the live values the features resolve at runtime.
@main
struct InterviewStarterApp: App {
  @MainActor static let store = Store(initialState: AppFeature.State()) { AppFeature() }

  /// `-harness-scenario <name>` swaps the API client for a fake with fixed data, so UI tests and
  /// simulator flows never reach the network. With no argument the app runs live.
  init() {
    let arguments = ProcessInfo.processInfo.arguments
    if let index = arguments.firstIndex(of: "-harness-scenario"),
      arguments.indices.contains(index + 1),
      let fake = APIClient.scenario(arguments[index + 1])
    {
      prepareDependencies { $0.apiClient = fake }
    }
  }

  var body: some Scene {
    WindowGroup {
      AppView(store: Self.store)
    }
  }
}
EOF
xcodebuild build -project InterviewStarter.xcodeproj -scheme InterviewStarter -destination 'generic/platform=iOS Simulator' -skipMacroValidation -skipPackagePluginValidation 2>&1 | grep -E "error:|BUILD" | tail -10
